    <div class="x321-carousel__buttons">
        <button type="button" data-carousel-prev aria-controls="{{ $carouselId }}" aria-label="@themeT('xd321.carousel.previous')"><i class="fa-solid fa-arrow-left" aria-hidden="true"></i></button>
